INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('e180ea7b-079b-44f8-88db-128ddc3ee492'::uuid, 'card_description', 'A Mycenaean fortress from 1400–1200 BC with walls so massive the Greeks thought Cyclopes built them. Legend says Heracles performed his Labours from here.', 'Its walls won it the Homeric epithet mighty walled Tiryns. Its features included a palace and Cyclopean tunnels, and in the lower town a cauldron held gold, silver and a Minoan signet ring.', 'teaser-card-s011:e180ea7b-079b-44f8-88db-128ddc3ee492:card_description', 'teaser-card-s011 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '114a250ec807662541508a30ed0f7133091d4d57d74d407070ea24c365502b2d|45572af1a982726bf89762c2b36344fe1daea8c5abec403731f264d738da6a75|45572af1a982726bf89762c2b36344fe1daea8c5abec403731f264d738da6a75', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Its walls won it the Homeric epithet mighty walled Tiryns. Its features included a palace and Cyclopean tunnels, and in the lower town a cauldron held gold, silver and a Minoan signet ring."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tiryns'' walls gave it the Homeric epithet mighty walled Tiryns [S4]; the site''s features included a palace [S4]; the site''s features included Cyclopean tunnels [S4]; a cauldron in the lower town held gold objects [S7]; a cauldron in the lower town held silver objects [S7]; a cauldron in the lower town held a Minoan signet ring [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tiryns is a Mycenaean hill fort (fortified citadel) in Greece, in Argolis in the Peloponnese [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; Tiryns is a Mycenaean archaeological site in Argolis in the Peloponnese, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; Its walls gave the city its epithet (its walls won it the epithet) [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; The epithet ''mighty walled Tiryns'' is Homeric [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; Its features included a palace [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; Its features included Cyclopean tunnels [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; In the lower town a cauldron held a deposit of precious items (a cauldron in Tiryns''s lower town) [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; The cauldron deposit held gold and silver objects [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]; The cauldron deposit included a Minoan signet ring [SUPPORTED: https://en.wikipedia.org/wiki/Tiryns]"}]'::jsonb),
    ('e2fc0a30-cd29-473d-ad34-7e109b098cb7'::uuid, 'card_description', 'Raised around 320 BC in Athens, this marble tomb for Demetria and Pamphile was among the last lavish grave stelae in the Kerameikos before a law banned such monuments.', 'In white marble, the Funerary Naiskos of Demetria and Pamphile shows two sisters: Pamphile, newly dead, seated on a luxurious chair, and Demetria, long dead, standing still beside her.', 'teaser-card-s011:e2fc0a30-cd29-473d-ad34-7e109b098cb7:card_description', 'teaser-card-s011 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '180f9f71932ccd54f111ede6855bf37ef10d504fe243e8bfc9f2a97c36261741|f8fc644725768893c1d42dcaae24dd0b9da18748ec47cc0e15017e0d10d22d5c|f8fc644725768893c1d42dcaae24dd0b9da18748ec47cc0e15017e0d10d22d5c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In white marble, the Funerary Naiskos of Demetria and Pamphile shows two sisters: Pamphile, newly dead, seated on a luxurious chair, and Demetria, long dead, standing still beside her."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the naiskos is made of white marble [S4]; it shows two women [S7]; the two women are sisters [S8]; Pamphile is the recently deceased one [S8]; Pamphile is seated on a luxurious chair [S7, S8]; Demetria had long predeceased her [S8]; Demetria stands still beside her [S7, S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Funerary Naiskos of Demetria and Pamphile is an ancient Greek tomb memorial (funerary monument, naiskos) in Athens, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; It is carved in white marble [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; It shows two women (two figures) [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; The two women, Pamphile and Demetria, are sisters [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; Pamphile is newly dead (recently deceased) [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; Pamphile is seated [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; Pamphile''s chair is luxurious [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; Demetria is long dead [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]; Demetria stands still beside Pamphile [SUPPORTED: https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile]"}]'::jsonb),
    ('e35c15c4-4ae7-4e7a-9f7c-e46e9561d0a0'::uuid, 'card_description', 'During World War II searchlights were installed at the site, and in 1996 it was evaluated before the construction of a new communications mast.', 'Not Bronze Age barrows but an unfinished Iron Age hill fort: Elworthy Barrows in Somerset, where a polished stone axe was found and searchlights were installed in World War II.', 'teaser-card-s011:e35c15c4-4ae7-4e7a-9f7c-e46e9561d0a0:card_description', 'teaser-card-s011 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '643ad79a0abd8990ed6bb8ac7d834751548b1ebeec227838df14927e0fbed7f5|2e6b31ec0fe33ee75e18454094440c308cd18958deac116129313e4ff0a6e235|2e6b31ec0fe33ee75e18454094440c308cd18958deac116129313e4ff0a6e235', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Not Bronze Age barrows but an unfinished Iron Age hill fort: Elworthy Barrows in Somerset, where a polished stone axe was found and searchlights were installed in World War II."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "it is not Bronze Age barrows [S1]; it is an unfinished Iron Age hill fort [S1]; it is in Somerset [S2]; a polished stone axe was found at the site [S3]; searchlights were installed at the site in World War II [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Elworthy Barrows is a hill fort (not a tomb/barrow site) in Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Elworthy_Barrows]; Elworthy Barrows is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Elworthy_Barrows]; It is not Bronze Age barrows despite its name [SUPPORTED: https://en.wikipedia.org/wiki/Elworthy_Barrows]; The hill fort is unfinished [SUPPORTED: https://en.wikipedia.org/wiki/Elworthy_Barrows]; It lies in Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Elworthy_Barrows]; A polished stone axe was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Elworthy_Barrows]; Searchlights were installed at the site in World War II [SUPPORTED: https://en.wikipedia.org/wiki/Elworthy_Barrows]"}]'::jsonb),
    ('e50a076d-5550-4c47-a49b-aced289dd4e0'::uuid, 'card_description', 'A Neolithic hilltop with paired causewayed enclosures from around 3500 BC, later converted into an Iron Age hillfort. Skeletons with arrowheads suggest violent attack.', 'Hambledon Hill, a chalk outcrop in Dorset, bears a prehistoric hill fort beside a Neolithic causewayed camp, occupied while the area was still wooded, before the Bronze Age clearances.', 'teaser-card-s011:e50a076d-5550-4c47-a49b-aced289dd4e0:card_description', 'teaser-card-s011 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '14030545a3782443d429bb7e7ad37784367f4f6f6a98c6520594bc78406420a9|964bae857d050d106f045c0d3c2b669c4b6bb8eb12651de536e2470298630857|964bae857d050d106f045c0d3c2b669c4b6bb8eb12651de536e2470298630857', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hambledon Hill, a chalk outcrop in Dorset, bears a prehistoric hill fort beside a Neolithic causewayed camp, occupied while the area was still wooded, before the Bronze Age clearances."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hambledon Hill is a chalk outcrop [S2]; it is in Dorset [S1]; it bears a prehistoric hill fort [S1]; a Neolithic causewayed camp lies beside the hill fort [S5]; the site was occupied while the area was still wooded [S4]; forest clearances came later, in the Bronze Age [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hambledon Hill is a prehistoric hill fort in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Hambledon_Hill]; The hill is a chalk outcrop [SUPPORTED: https://en.wikipedia.org/wiki/Hambledon_Hill]; The hill lies in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Hambledon_Hill]; Beside the hill fort stands a Neolithic causewayed camp (enclosure) [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Hambledon_Hill]; The hill was occupied in the Neolithic, while the area was still wooded [SUPPORTED: https://en.wikipedia.org/wiki/Hambledon_Hill]; The forest clearances came later, in the Bronze Age (the occupation predates the Bronze Age clearances) [SUPPORTED: https://en.wikipedia.org/wiki/Hambledon_Hill]"}]'::jsonb),
    ('e522ea1d-4166-429d-8cac-8d31f72b944b'::uuid, 'card_description', 'An Early Iron Age hillfort that was occupied for only a brief period before being abandoned. In medieval times the site was reused as a moated settlement with fishponds.', 'In north Bedford, Mowsbury Hill holds an early Iron Age hillfort with a single rampart, occupied for a limited period; in medieval times it became a moated settlement with two fishponds.', 'teaser-card-s011:e522ea1d-4166-429d-8cac-8d31f72b944b:card_description', 'teaser-card-s011 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '7521d0a948c7fa52946c9857b764684c3ab83db7404b7cb179f108c71402b0fb|2d5f8e40eacd2c051825ce33c4607c49984cf36a7e32d17ef0860137ccce17be|2d5f8e40eacd2c051825ce33c4607c49984cf36a7e32d17ef0860137ccce17be', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In north Bedford, Mowsbury Hill holds an early Iron Age hillfort with a single rampart, occupied for a limited period; in medieval times it became a moated settlement with two fishponds."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mowsbury Hill is in north Bedford [S1]; it holds an early Iron Age hillfort [S2]; the hillfort is univallate, with a single rampart [S2]; it was occupied for a limited period [S2]; in medieval times it was a moated settlement [S3]; the moated settlement had two fishponds [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mowsbury Hill is a hillfort site in north Bedford [SUPPORTED: https://en.wikipedia.org/wiki/Mowsbury_Hill]; Archaeological excavation shows the site is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Mowsbury_Hill]; The hillfort dates to the early Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Mowsbury_Hill]; The hillfort has a single rampart [SUPPORTED: https://en.wikipedia.org/wiki/Mowsbury_Hill]; It was occupied for a limited period [SUPPORTED: https://en.wikipedia.org/wiki/Mowsbury_Hill]; In medieval times the site became a moated settlement [SUPPORTED: https://en.wikipedia.org/wiki/Mowsbury_Hill]; The medieval settlement had two fishponds [SUPPORTED: https://en.wikipedia.org/wiki/Mowsbury_Hill]"}]'::jsonb),
    ('e62c980a-351d-40c1-8297-05f52f72a59c'::uuid, 'card_description', 'A 100-metre Roman bridge built as a double-decker: the bottom vault carried a brook, while arches on top connected two hills. It functioned as both bridge and tunnel.', 'Over the Cakircak stream in ancient Caria, the Nysa Bridge runs some 100 m like a tunnel, though built entirely above ground: a Roman vault carrying the area before the city theatre.', 'teaser-card-s011:e62c980a-351d-40c1-8297-05f52f72a59c:card_description', 'teaser-card-s011 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '793f535abcd7286dac87de24db888a9afb6a46dc4c90aa657e6696c10d9aa3ba|ac7f113ae8d5deb2197233b8a88d3d909b8cd181c6861e7268d59c2ff1b18605|ac7f113ae8d5deb2197233b8a88d3d909b8cd181c6861e7268d59c2ff1b18605', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Over the Cakircak stream in ancient Caria, the Nysa Bridge runs some 100 m like a tunnel, though built entirely above ground: a Roman vault carrying the area before the city theatre."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Nysa Bridge spans the Cakircak stream [S1, S6]; it lies in ancient Caria [S1]; it is a Roman bridge/vault [S1, S7]; it runs some 100 m [S2, S6]; it looks like a tunnel [S6]; it is built entirely above ground [S6]; it is a vault [S4, S7]; it carries the area in front of the city theatre [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Nysa Bridge is a bridge (a Roman structure of late imperial date) over a stream [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; The stream it crosses is the Cakircak stream [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; It lies in ancient Caria [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; It is in Turkey (Tuerkiye) [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; It is Roman [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; The structure runs some 100 m [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; It has the appearance of a tunnel [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; Although it looks like a tunnel, it was built entirely above ground [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; It is a vault (a single semi-circular vault spanning the stream) [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]; It carried (served as a substructure for) the area in front of the city theatre [SUPPORTED: https://en.wikipedia.org/wiki/Nysa_Bridge]"}]'::jsonb),
    ('e65caba7-ac7b-4b9c-a0d5-a634cfbc9fc3'::uuid, 'card_description', 'A Roman encampment on Dere Street, near the border. Four overlapping camp phases are visible in the earthworks — decades of rebuilding on one spot.', 'Beside Dere Street, almost on the border with Scotland, Chew Green yielded a Roman fort, two fortlets and two camps, the largest a square of about 17 acres ringed by rampart and ditch.', 'teaser-card-s011:e65caba7-ac7b-4b9c-a0d5-a634cfbc9fc3:card_description', 'teaser-card-s011 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '29032c8bead69d4c5a64acc89dab4ecbb55a9cfa2c6e8e831f3812aa8fdb3738|510552228deff3d82602ed1b1f233b26b3db04213424017155a519786fab00b3|510552228deff3d82602ed1b1f233b26b3db04213424017155a519786fab00b3', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Beside Dere Street, almost on the border with Scotland, Chew Green yielded a Roman fort, two fortlets and two camps, the largest a square of about 17 acres ringed by rampart and ditch."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies beside Dere Street [S2]; it is almost on the border with Scotland [S2]; excavation yielded a Roman fort [S3]; it also yielded two fortlets [S3]; it also yielded two camps [S3]; the largest camp structure is a square [S4]; the largest is about 17 acres [S4]; it is ringed by a rampart and ditch [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chew Green is a Roman military site (an encampment with a fort, fortlets and camps) [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; It lies in England (Northumberland) [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Chew_Green]; It lies beside (adjacent to) Dere Street [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; It is almost on the border with Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; Excavation at Chew Green yielded a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; There are two fortlets [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; There are two camps [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; The largest camp is a square [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; The largest camp encloses about 17 acres [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]; The largest camp is ringed by a rampart and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Chew_Green]"}]'::jsonb),
    ('e6de5091-b046-45e8-bb6a-a81c99b2fbe2'::uuid, 'card_description', '13th century BC. Ramesses II''s mortuary temple measured 210 by 178 metres. Its shattered 1,000-tonne colossus — once 17 metres tall — inspired Shelley''s poem ''Ozymandias'' in 1818.', 'Across the Nile from Luxor, the Ramesseum, memorial temple of Ramesses II, keeps a true arch of mud brick held only by mortar: the oldest such arch still standing in Egypt, circa 1300 BC.', 'teaser-card-s011:e6de5091-b046-45e8-bb6a-a81c99b2fbe2:card_description', 'teaser-card-s011 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '1766a3f1c8937b7c1266f005fdf65c04585a487cc935b630b44010d0c8a439a9|f8781c66a689143a3d91f6f0967c598e2ece92c7780657bd9fb69d2b501b34cb|f8781c66a689143a3d91f6f0967c598e2ece92c7780657bd9fb69d2b501b34cb', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Across the Nile from Luxor, the Ramesseum, memorial temple of Ramesses II, keeps a true arch of mud brick held only by mortar: the oldest such arch still standing in Egypt, circa 1300 BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Ramesseum lies across the Nile from Luxor [S2]; it is the memorial temple of Ramesses II [S1]; it keeps a true arch of mud brick [S6]; the arch is held only by mortar [S6]; it is the oldest such arch still standing in Egypt [S7]; the arch dates to circa 1300 BC [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Ramesseum is a memorial temple [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]; It is the memorial temple of Ramesses II [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]; It lies in Egypt, across the Nile from Luxor [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]; The site keeps true arches (a true arch) [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]; The arch is of mud brick [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]; The arch is held only by mortar (the bricks are not wedge-shaped voussoirs) [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]; It is the oldest such arch still standing in Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]; The arch dates to circa 1300 BC [SUPPORTED: https://en.wikipedia.org/wiki/Ramesseum]"}]'::jsonb),
    ('e77b1f25-4675-472d-b63d-ff76fae4c08d'::uuid, 'card_description', 'A collapsed Neolithic dolmen with a 3.6 by 2.6 meter capstone resting on two support stones. A missing stone, removed before 1873, likely caused the collapse.', 'On Anglesey, the fallen capstone of Ty Mawr Burial Chamber, roughly 3.6 metres by 2.6 metres, rests on two flattened stones. Its covering cairn was removed, but early maps marked it.', 'teaser-card-s011:e77b1f25-4675-472d-b63d-ff76fae4c08d:card_description', 'teaser-card-s011 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'd2381615318f7dbd82144327beb97f974b118d848cbe6baf5ef105abc6278f8d|19e9de3885d2d4dafaf1922f1bfab238cb84139c16eeaf8665f8cf8ba9961d34|19e9de3885d2d4dafaf1922f1bfab238cb84139c16eeaf8665f8cf8ba9961d34', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Anglesey, the fallen capstone of Ty Mawr Burial Chamber, roughly 3.6 metres by 2.6 metres, rests on two flattened stones. Its covering cairn was removed, but early maps marked it."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is on Anglesey [S1]; its capstone has fallen [S2]; the capstone measures roughly 3.6 m by 2.6 m [S2]; the capstone rests on two flattened stones [S2]; it had a covering cairn [S4, S5]; the cairn was removed [S5]; early maps marked the cairn [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ty Mawr Burial Chamber is a burial chamber (collapsed Neolithic chambered tomb / dolmen) [SUPPORTED: https://coflein.gov.uk/en/sites/302558]; It is on Anglesey (Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Ty_Mawr_Burial_Chamber]; The capstone has fallen (the chamber is collapsed with a fallen capstone) [SUPPORTED: https://en.wikipedia.org/wiki/Ty_Mawr_Burial_Chamber]; The capstone measures roughly 3.6 metres by 2.6 metres [SUPPORTED: https://coflein.gov.uk/en/sites/302558]; The capstone rests on two flattened stones [SUPPORTED: https://en.wikipedia.org/wiki/Ty_Mawr_Burial_Chamber]; The site had a covering cairn [SUPPORTED: https://en.wikipedia.org/wiki/Ty_Mawr_Burial_Chamber]; The covering cairn has been removed [SUPPORTED: https://en.wikipedia.org/wiki/Ty_Mawr_Burial_Chamber]; The cairn was marked on early maps [SUPPORTED: https://coflein.gov.uk/en/sites/302558]"}]'::jsonb),
    ('e790a37d-2265-48ad-8e62-67fb72ec73c7'::uuid, 'card_description', 'The largest Hallstatt-period tumulus in Central Europe, dated by tree rings to exactly 616 BC. Over 100 secondary burials surround the central Celtic prince''s grave.', 'In the Iron Age mound of Magdalenenberg lay an early Celtic prince, his tomb dated to 616 BCE. Around 500 BCE robbers plundered it, and archaeologists later found their wooden spades.', 'teaser-card-s011:e790a37d-2265-48ad-8e62-67fb72ec73c7:card_description', 'teaser-card-s011 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '5321810a377586c92f909fe0ad57dca3c14b723c1694a754d53403e554882d9a|561f0f6152663189ba65a90dc942bb765b8a5539bf53e6355f148d51e361518d|561f0f6152663189ba65a90dc942bb765b8a5539bf53e6355f148d51e361518d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the Iron Age mound of Magdalenenberg lay an early Celtic prince, his tomb dated to 616 BCE. Around 500 BCE robbers plundered it, and archaeologists later found their wooden spades."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Magdalenenberg is an Iron Age mound [S1]; an early Celtic prince lay in it [S3]; his tomb is dated to 616 BCE [S3]; around 500 BCE robbers plundered the tomb [S6]; archaeologists later found the robbers'' wooden spades [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Magdalenenberg is an Iron Age burial mound (tumulus) in Germany [SUPPORTED: https://en.wikipedia.org/wiki/Magdalenenberg]; An early Celtic prince was buried in its central tomb [SUPPORTED: https://en.wikipedia.org/wiki/Magdalenenberg]; The tomb is dated to 616 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Magdalenenberg]; Around 500 BCE the tomb was plundered [SUPPORTED: https://en.wikipedia.org/wiki/Magdalenenberg]; The plunderers were robbers (grave robbers) [SUPPORTED: https://en.wikipedia.org/wiki/Magdalenenberg]; Archaeologists later found the robbers'' wooden spades [SUPPORTED: https://en.wikipedia.org/wiki/Magdalenenberg]"}]'::jsonb),
    ('e7ad39e0-062c-4fe6-a534-3126b72c9e9c'::uuid, 'card_description', 'Woodcutts Settlement is an archaeological site of the late Iron Age and Romano-British period on Cranborne Chase.', 'On Cranborne Chase lies Woodcutts Settlement, a late Iron Age and Romano-British site: a roughly circular enclosure of bank and ditch that Augustus Pitt Rivers excavated in 1884 and 1885.', 'teaser-card-s011:e7ad39e0-062c-4fe6-a534-3126b72c9e9c:card_description', 'teaser-card-s011 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '798493ad41b5b72dd201fafb69340715a95ea99219fbb8c9327bce3f2729fcf7|3c275f1651b562af5c7de010c52ef0c9dec2d2744e5236b6473bb8ef3fda31d2|3c275f1651b562af5c7de010c52ef0c9dec2d2744e5236b6473bb8ef3fda31d2', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Cranborne Chase lies Woodcutts Settlement, a late Iron Age and Romano-British site: a roughly circular enclosure of bank and ditch that Augustus Pitt Rivers excavated in 1884 and 1885."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Woodcutts Settlement lies on Cranborne Chase [S1]; it is a late Iron Age and Romano-British site [S1]; it has a roughly circular enclosure [S4]; the enclosure is formed of a bank and a ditch [S4]; Augustus Pitt Rivers excavated the site [S6, S7]; the main enclosure was excavated [S8]; the excavation took place in 1884 and 1885 [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Woodcutts Settlement is an archaeological site (a settlement) of the late Iron Age and Romano-British period [SUPPORTED: https://en.wikipedia.org/wiki/Woodcutts_Settlement]; It lies on Cranborne Chase [SUPPORTED: https://en.wikipedia.org/wiki/Woodcutts_Settlement]; The site is a settlement of late Iron Age / Romano-British date (a prehistoric settlement surrounded by a bank and ditch) [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO6059]; It is a roughly circular enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Woodcutts_Settlement]; The enclosure is defined by a bank and a ditch [SUPPORTED: https://en.wikipedia.org/wiki/Woodcutts_Settlement]; Augustus Pitt Rivers excavated the site [SUPPORTED: https://en.wikipedia.org/wiki/Woodcutts_Settlement]; The excavation took place in 1884 and 1885 [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO6059]"}]'::jsonb),
    ('e8234ff9-0b4e-4961-a0ca-f15d09232a0a'::uuid, 'card_description', 'Neolithic henge in Wiltshire''s Vale of Pewsey, known only from aerial cropmarks - a broad circular ditch near the River Avon. Positioned south of the massive Marden Henge in a dense ritual landscape.', 'Seen only as a cropmark from the air, Wilsford Henge gave up an early Bronze Age crouched burial of an adolescent child, with beaker sherds and necklace beads, in the 2015 excavations.', 'teaser-card-s011:e8234ff9-0b4e-4961-a0ca-f15d09232a0a:card_description', 'teaser-card-s011 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'e95b41047a30d5c485dd9950cf5b3d323a782855d9fa80b4e6f775f5fc975a9d|1540ee290723246a7db382010b57b628c3110c2ad8ab0125cc61573ec8dc428b|1540ee290723246a7db382010b57b628c3110c2ad8ab0125cc61573ec8dc428b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Seen only as a cropmark from the air, Wilsford Henge gave up an early Bronze Age crouched burial of an adolescent child, with beaker sherds and necklace beads, in the 2015 excavations."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the henge is seen only as a cropmark from the air [S3]; the site yielded a crouched burial [S8]; the burial is early Bronze Age [S8]; the burial is of an adolescent child [S8]; it included sherds of beaker pottery [S8]; it included necklace beads [S8]; the finds came in the 2015 excavations [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Wilsford Henge is a henge (a Neolithic henge in Wiltshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Wilsford_Henge]; The henge is seen only as a cropmark from the air [SUPPORTED: https://en.wikipedia.org/wiki/Wilsford_Henge]; The 2015 excavations found a burial at the henge [SUPPORTED: https://en.wikipedia.org/wiki/Wilsford_Henge]; The burial is early Bronze Age [SUPPORTED: https://marlborough.news/news/archaeologists-unearth-a-skeleton-in-a-bronze-age-burial-at-the-wilsford-henge-excavation-near-marden/]; The burial is crouched [SUPPORTED: https://en.wikipedia.org/wiki/Wilsford_Henge]; The burial is of an adolescent child [SUPPORTED: https://archive.reading.ac.uk/news-events/2015/July/pr638964.html]; The burial included beaker sherds [SUPPORTED: https://en.wikipedia.org/wiki/Wilsford_Henge]; The burial included necklace beads [SUPPORTED: https://en.wikipedia.org/wiki/Wilsford_Henge]; The excavation that found the burial took place in 2015 [SUPPORTED: https://en.wikipedia.org/wiki/Wilsford_Henge]"}]'::jsonb),
    ('e8ef0cd6-6f7b-4b96-905d-e3eb22423006'::uuid, 'card_description', 'A town named after the cult of Apollo, who had a major temple here in pre-Roman times. Both the original village and its twin were destroyed by the 1631 eruption of Vesuvius.', 'At Pollena Trocchia, Vesuvius buried the lower floors of a Roman villa''s baths in 472, yet occupation went on in the upper levels until a further eruption, either that of 505 or 512.', 'teaser-card-s011:e8ef0cd6-6f7b-4b96-905d-e3eb22423006:card_description', 'teaser-card-s011 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '21fe6328c119b39500b08561c361646b291b0a798847c548436d451c10fe1753|7ebb453bfda37af2c0fa536af5e396e889ab86230c2c1e0e5dd3f0b033f5af1b|7ebb453bfda37af2c0fa536af5e396e889ab86230c2c1e0e5dd3f0b033f5af1b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Pollena Trocchia, Vesuvius buried the lower floors of a Roman villa''s baths in 472, yet occupation went on in the upper levels until a further eruption, either that of 505 or 512."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is at Pollena Trocchia [S1]; the baths belonged to a Roman villa [S1]; the eruptions of Vesuvius in 472 buried the lower floors [S3]; occupation went on in the upper levels after that [S3]; occupation ended with a further eruption [S3, W1]; it is uncertain whether that eruption was the one of 505 or of 512 [W1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Pollena Trocchia are the baths of a Roman villa (Masseria De Carolis), an excavated Roman site [SUPPORTED: https://en.wikipedia.org/wiki/Pollena_Trocchia]; The eruption of Vesuvius in 472 buried the lower floors of the villa''s baths [SUPPORTED: https://en.wikipedia.org/wiki/Pollena_Trocchia]; The burial happened in 472 [SUPPORTED: https://www.apollineproject.org/pollena.html]; Occupation went on in the upper levels after the 472 burial [SUPPORTED: https://en.wikipedia.org/wiki/Pollena_Trocchia]; Occupation ended with a further eruption of Vesuvius [SUPPORTED: https://www.apollineproject.org/pollena.html]; The further eruption was either that of 505 or that of 512 (not settled which) [SUPPORTED: https://www.apollineproject.org/pollena.html]"}, {"source": "web fact W1", "url": "https://www.apollineproject.org/pollena.html", "quote": "Human habitation finally comes to an end with a further eruption. This could be either that of 505 or 512."}]'::jsonb),
    ('e95ae624-060a-40ef-a821-0983a25b68bb'::uuid, 'card_description', 'Sub-triangular and 6.9 hectares in area, this bivallate hillfort on the eastern edge of Salisbury Plain was raised over a Neolithic settlement. Double ditches reinforce natural defensive slopes.', 'On the eastern edge of Salisbury Plain, Sidbury Hill rises behind double ditch and rampart, an Iron Age hillfort built on a Neolithic settlement, where flint flakes and tools were recovered.', 'teaser-card-s011:e95ae624-060a-40ef-a821-0983a25b68bb:card_description', 'teaser-card-s011 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '27e68b9d9f8165bc61b941fcc2d8d62878c1c4c54ed3ccf50252a18505debe88|2c19faed4e263b24bdc7029c8fd43b23b273a633bae097ab151d4caccca73479|2c19faed4e263b24bdc7029c8fd43b23b273a633bae097ab151d4caccca73479', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the eastern edge of Salisbury Plain, Sidbury Hill rises behind double ditch and rampart, an Iron Age hillfort built on a Neolithic settlement, where flint flakes and tools were recovered."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Sidbury Hill lies on the eastern edge of Salisbury Plain [S1]; it has a double ditch and rampart [S1, S3]; it is an Iron Age hillfort [S1]; it was built on a Neolithic settlement [S2]; flint flakes and tools were recovered [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Sidbury Hill is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Sidbury_Hill]; It lies on the eastern edge of Salisbury Plain [SUPPORTED: https://en.wikipedia.org/wiki/Sidbury_Hill]; The hillfort is defended by a double ditch and rampart [SUPPORTED: https://en.wikipedia.org/wiki/Sidbury_Hill]; The hillfort was built on the site of a Neolithic settlement [SUPPORTED: https://www.digitaldigging.net/sidbury-camp-wiltshire/]; Flint flakes and tools were recovered [SUPPORTED: https://en.wikipedia.org/wiki/Sidbury_Hill]"}]'::jsonb),
    ('e99aac35-d2da-448f-8cd2-d07c02ae007c'::uuid, 'card_description', 'A Neolithic entrance grave considered one of the smallest and best-preserved burial monuments in all of Britain. The unique Scillonian type is found only in two areas.', 'Out on the Penwith Moors between Madron and Morvah, near the hamlet of Bosiliack in Cornwall, Bosiliack Barrow was excavated in 1984, causing little disturbance to the ancient site.', 'teaser-card-s011:e99aac35-d2da-448f-8cd2-d07c02ae007c:card_description', 'teaser-card-s011 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'bd572ecc0c863c940d030bf2481456de1e4f505196230ff39eb423ccecf0a72e|88611db36e25144057c4ba29d670160cbdd02760a1ab7976c27f54715590379a|88611db36e25144057c4ba29d670160cbdd02760a1ab7976c27f54715590379a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Out on the Penwith Moors between Madron and Morvah, near the hamlet of Bosiliack in Cornwall, Bosiliack Barrow was excavated in 1984, causing little disturbance to the ancient site."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bosiliack Barrow lies on the Penwith Moors [S1]; it is between Madron and Morvah [S1]; it is near the hamlet of Bosiliack in Cornwall [S1]; it was excavated in 1984 [S2]; the excavation caused little disturbance to the ancient site [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bosiliack Barrow is a barrow, a burial monument of the entrance-grave type (a tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Bosiliack_Barrow]; It lies on the Penwith Moors between Madron and Morvah [SUPPORTED: https://en.wikipedia.org/wiki/Bosiliack_Barrow]; It lies near the hamlet of Bosiliack in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Bosiliack_Barrow]; The barrow was excavated in 1984 [SUPPORTED: https://cornishancientsites.com/ancient-sites/1851/]; The excavation caused little disturbance to the ancient site [SUPPORTED: https://en.wikipedia.org/wiki/Bosiliack_Barrow]"}]'::jsonb),
    ('ea209a12-df80-46f7-9985-4ccd0ae5fc99'::uuid, 'card_description', 'Four layers of uninterrupted occupation from the 8th to 1st century BC mark this as a city of ancient Colchis. Sophisticated local goldwork rivals imported Greek pottery.', 'Since 1947, studies around Vani have revealed a rich city of ancient Colchis whose name is still unknown: sacrificial altars cut in the rocky ground, wooden structures and rich burials.', 'teaser-card-s011:ea209a12-df80-46f7-9985-4ccd0ae5fc99:card_description', 'teaser-card-s011 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '83362904b04705a8249bd8ba385db9bc12df6e6752b425f34ca60770dbde0c78|864feeca5f162c7726c9b75ac57746ac8745e9719f3ef777c97f0ac391e1c3ee|864feeca5f162c7726c9b75ac57746ac8745e9719f3ef777c97f0ac391e1c3ee', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Since 1947, studies around Vani have revealed a rich city of ancient Colchis whose name is still unknown: sacrificial altars cut in the rocky ground, wooden structures and rich burials."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "studies around Vani have been carried out since 1947 [S1]; they revealed a rich city [S1]; the city belonged to ancient Colchis [S1]; the name of the settlement is still unknown [S2]; sacrificial altars cut in the rocky ground were found [S5]; wooden structures (remains) were found [S5]; rich burials were found [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Vani, in western Georgia, is a rich city (settlement) of ancient Colchis [SUPPORTED: https://en.wikipedia.org/wiki/Vani]; The site lies at Vani in the Imereti region of western Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Vani]; Systematic archaeological studies around Vani have been carried out since 1947 [SUPPORTED: https://en.wikipedia.org/wiki/Vani]; The name of the ancient city at Vani is still unknown [SUPPORTED: https://en.wikipedia.org/wiki/Vani]; Vani has sacrificial altars cut in the rocky ground [SUPPORTED: https://en.wikipedia.org/wiki/Vani]; Vani has remains of wooden structures [SUPPORTED: https://en.wikipedia.org/wiki/Vani]; Vani has rich burials [SUPPORTED: https://en.wikipedia.org/wiki/Vani]"}]'::jsonb),
    ('eaf2f471-84d2-4661-8781-6a81241b11fb'::uuid, 'card_description', 'Fernacre carries a pivotal location between Rough Tor located due north and Brown Willy located due east.', 'On Bodmin Moor, Fernacre, one of the biggest stone circles in Cornwall, stands on the slopes of the De Lank River, with Rough Tor due north and Brown Willy due east.', 'teaser-card-s011:eaf2f471-84d2-4661-8781-6a81241b11fb:card_description', 'teaser-card-s011 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', 'e489ac3f7d04cb6ec5c66ad9a24725c5250d7f066eadff35561e4d783ea2761e|5031d6a99bb21ec3c5da4a5308f1739e557e00837384959e14cc12f81a9f4f03|5031d6a99bb21ec3c5da4a5308f1739e557e00837384959e14cc12f81a9f4f03', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Bodmin Moor, Fernacre, one of the biggest stone circles in Cornwall, stands on the slopes of the De Lank River, with Rough Tor due north and Brown Willy due east."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Fernacre is on Bodmin Moor [S1]; it is one of the biggest stone circles in Cornwall [S2]; it stands on the slopes of the De Lank River [S1]; Rough Tor lies due north of it [S4]; Brown Willy lies due east of it [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Fernacre is a stone circle on Bodmin Moor in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Fernacre]; Fernacre is on Bodmin Moor, Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Fernacre]; Fernacre is one of the biggest stone circles in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Fernacre]; Fernacre stands on the slopes of the De Lank River [SUPPORTED: https://en.wikipedia.org/wiki/Fernacre]; Rough Tor lies due north of Fernacre [SUPPORTED: https://en.wikipedia.org/wiki/Fernacre]; Brown Willy lies due east of Fernacre [SUPPORTED: https://en.wikipedia.org/wiki/Fernacre]"}]'::jsonb),
    ('edb4cd03-cbf2-412f-9861-bb88db0d2027'::uuid, 'card_description', 'A mountain at 4,302 metres with an archaeological site declared a National Cultural Heritage. It lies north of the mountain and site of Intikancha.', 'High in the Andes of Peru, the mountain Pukarani rises about 4,301.9 m and bears an archaeological site of the same name, declared National Cultural Heritage, north of Intikancha.', 'teaser-card-s011:edb4cd03-cbf2-412f-9861-bb88db0d2027:card_description', 'teaser-card-s011 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '1eb845cc0006396b3436e3e79b3c77f7502a556d3603b73edbaab112ac4faa16|8ae58f1fcb8ed5c34e7ce122670ab184fc784d2cd42719e018328696f8bfcdda|8ae58f1fcb8ed5c34e7ce122670ab184fc784d2cd42719e018328696f8bfcdda', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "High in the Andes of Peru, the mountain Pukarani rises about 4,301.9 m and bears an archaeological site of the same name, declared National Cultural Heritage, north of Intikancha."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pukarani is in the Andes of Peru [S1]; Pukarani is a mountain about 4,301.9 m high [S1]; it bears an archaeological site of the same name [S1]; the archaeological site was declared National Cultural Heritage [S3]; it lies north of Intikancha [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pukarani is a mountain with an archaeological site of the same name [SUPPORTED: https://en.wikipedia.org/wiki/Pukarani_(Peru)]; Pukarani is in the Andes of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Pukarani_(Peru)]; The mountain Pukarani is about 4,301.9 m high [SUPPORTED: https://en.wikipedia.org/wiki/Pukarani_(Peru)]; The archaeological site of Pukarani was declared a National Cultural Heritage [SUPPORTED: https://en.wikipedia.org/wiki/Pukarani_(Peru)]; The Pukarani site lies north of Intikancha [SUPPORTED: https://en.wikipedia.org/wiki/Pukarani_(Peru)]"}]'::jsonb),
    ('ee091b60-f72c-4e85-be61-baa970aa0630'::uuid, 'card_description', 'A Bronze Age coastal settlement with some of the best-preserved monumental architecture of the 2nd millennium BC anywhere in the Mediterranean.', 'On the Adriatic coast of Apulia, Roca Archaeological Site holds Poesia Cave, a large natural cavity where thousands of dedications to a local deity were written in Greek, Messapic and Latin.', 'teaser-card-s011:ee091b60-f72c-4e85-be61-baa970aa0630:card_description', 'teaser-card-s011 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '948009429aa618851b5b18a3bf8822cf4e49a6abffaac743b5d9a48645889694|60d8f110670aaf8dc576c2a28b909bcbe0af61724b34e4e3c80a3c14947c9658|60d8f110670aaf8dc576c2a28b909bcbe0af61724b34e4e3c80a3c14947c9658', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Adriatic coast of Apulia, Roca Archaeological Site holds Poesia Cave, a large natural cavity where thousands of dedications to a local deity were written in Greek, Messapic and Latin."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies on the Adriatic coast of Apulia [S1]; the site holds Poesia Cave [S3, S4]; Poesia Cave is a large natural cavity [S3]; thousands of dedications were written there [S3]; the dedications were to a local deity [S3]; they were written in Greek, Messapic and Latin [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Roca is an archaeological site on the Adriatic coast of Apulia [SUPPORTED: https://en.wikipedia.org/wiki/Roca_(archaeological_site)]; Poesia Cave, a large natural cavity, is part of the Roca site [SUPPORTED: https://en.wikipedia.org/wiki/Roca_(archaeological_site)]; Poesia Cave was used for cult practices [SUPPORTED: https://en.wikipedia.org/wiki/Roca_(archaeological_site)]; Thousands of dedications were written in Poesia Cave [SUPPORTED: https://en.wikipedia.org/wiki/Roca_(archaeological_site)]; The dedications were to a local deity [SUPPORTED: https://en.wikipedia.org/wiki/Roca_(archaeological_site)]; The dedications were written in Greek, Messapic and Latin [SUPPORTED: https://en.wikipedia.org/wiki/Roca_(archaeological_site)]"}]'::jsonb),
    ('ef0072cc-9021-4f21-8e22-4163967650d6'::uuid, 'card_description', 'A restored stone circle of 19 granite blocks, the sole survivor of three circles once aligned east-west. Its Cornish name means "Stones of the Dance."', 'Near St Just, the 19 granite stones of Tregeseal East Stone Circle, The Dancing Stones, form a rough circle around 21 m across, but only the eastern ones may still stand where first set.', 'teaser-card-s011:ef0072cc-9021-4f21-8e22-4163967650d6:card_description', 'teaser-card-s011 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '35bc4d4132d2335efa48d8385e3423b603a5ef7480364239bd43de6124ec1784|d06fc5790f8ac59038f398d50291fd9344579e5a8d4e7cc7473b42bc7000a27c|d06fc5790f8ac59038f398d50291fd9344579e5a8d4e7cc7473b42bc7000a27c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near St Just, the 19 granite stones of Tregeseal East Stone Circle, The Dancing Stones, form a rough circle around 21 m across, but only the eastern ones may still stand where first set."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the circle is near St Just [S1]; it consists of 19 granite stones [S2, S4]; it is known as The Dancing Stones [S2]; the stones form a rough circle [S4]; the circle is around 21 m across [S4]; only the eastern stones may still be in their original positions [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tregeseal East is a prehistoric stone circle near St Just in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Tregeseal_East_stone_circle]; The circle has 19 granite stones [SUPPORTED: https://en.wikipedia.org/wiki/Tregeseal_East_stone_circle]; The circle is also known as The Dancing Stones [SUPPORTED: https://en.wikipedia.org/wiki/Tregeseal_East_stone_circle]; The stones form a rough circle around 21 m across [SUPPORTED: https://en.wikipedia.org/wiki/Tregeseal_East_stone_circle]; The circle was substantially rebuilt and restored over the centuries, so the stones are not all in their first positions [SUPPORTED: https://en.wikipedia.org/wiki/Tregeseal_East_stone_circle]; Only the eastern stones may still stand where first set [SUPPORTED: https://en.wikipedia.org/wiki/Tregeseal_East_stone_circle]"}]'::jsonb),
    ('ef1ee8c0-f6bd-4886-bd66-8a6106ac5ca4'::uuid, 'card_description', 'An Early Bronze Age settlement occupied from 3000 to 2200 BC. It belonged to the Kura-Araxes culture, which spread from the Caucasus to the Levant.', 'On a hill in Yerevan, cyclopean walls with towers ringed the Shengavit Settlement: stone and mud-brick homes, some with ritual hearths, and nearby silos of wheat and barley.', 'teaser-card-s011:ef1ee8c0-f6bd-4886-bd66-8a6106ac5ca4:card_description', 'teaser-card-s011 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'fb57fac8e7739e56253bf6190a83e674658f0d638dca61d05bb2b2a66214f9b6|5cb86ea6a65e604eb57d79342a7a1da8390ca85271f350a7804ff117d45f6974|5cb86ea6a65e604eb57d79342a7a1da8390ca85271f350a7804ff117d45f6974', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a hill in Yerevan, cyclopean walls with towers ringed the Shengavit Settlement: stone and mud-brick homes, some with ritual hearths, and nearby silos of wheat and barley."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the settlement lies on a hill in Yerevan [S1]; cyclopean walls with towers surrounded the settlement [S4]; the buildings were of stone and mud-brick [S5]; the buildings were dwellings (homes) [S5, S6]; some of the residential structures held ritual hearths [S6]; nearby silos stored wheat and barley [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Shengavit Settlement is an archaeological site (a settlement) in Yerevan, Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Shengavit_(site)]; The site was inhabited as a settlement in the Early Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Shengavit_(site)]; The site lies on a hill in Yerevan [SUPPORTED: https://en.wikipedia.org/wiki/Shengavit_(site)]; Cyclopean walls with towers surrounded the settlement [SUPPORTED: https://en.wikipedia.org/wiki/Shengavit_(site)]; The dwellings were built of stone and mud-brick [SUPPORTED: https://en.wikipedia.org/wiki/Shengavit_(site)]; Some residential structures contained ritual hearths [SUPPORTED: https://en.wikipedia.org/wiki/Shengavit_(site)]; Nearby silos stored wheat and barley [SUPPORTED: https://en.wikipedia.org/wiki/Shengavit_(site)]"}]'::jsonb),
    ('efa6ff4f-1d6a-4121-b1c0-f3d21a6c4ce6'::uuid, 'card_description', 'The original garrison of Segedunum is unknown, but in the 2nd century Cohors II Nerviorum was stationed there.', 'At the eastern end of Hadrian''s Wall, by the River Tyne, lay Segedunum. Its first garrison is unknown; later the Fourth Cohort of the Lingones held the fort, abandoned round about 400 AD.', 'teaser-card-s011:efa6ff4f-1d6a-4121-b1c0-f3d21a6c4ce6:card_description', 'teaser-card-s011 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '5585e5d0bd13efad71a945d8ee4b543606086d09ba21f8f0409010e45c6588cc|689d843ead83b87e5e2faccc0b60cc7c9b1af7ba876133cd966422e1887172ed|689d843ead83b87e5e2faccc0b60cc7c9b1af7ba876133cd966422e1887172ed', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At the eastern end of Hadrian''s Wall, by the River Tyne, lay Segedunum. Its first garrison is unknown; later the Fourth Cohort of the Lingones held the fort, abandoned round about 400 AD."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Segedunum lay at the eastern end of Hadrian''s Wall [S2]; it lay by the River Tyne [S2]; its original (first) garrison is unknown [S4]; later the Fourth Cohort of the Lingones held the fort [S5]; the fort was abandoned round about 400 AD [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Segedunum was a Roman fort (at Wallsend, North Tyneside, England) [SUPPORTED: https://en.wikipedia.org/wiki/Segedunum]; The fort lay at the eastern end of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Segedunum]; The fort lay by (near the banks of) the River Tyne [SUPPORTED: https://en.wikipedia.org/wiki/Segedunum]; The original (first) garrison of Segedunum is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Segedunum]; Later the Fourth Cohort of the Lingones occupied the fort (3rd and 4th centuries) [SUPPORTED: https://en.wikipedia.org/wiki/Segedunum]; The fort was abandoned round about 400 AD [SUPPORTED: https://en.wikipedia.org/wiki/Segedunum]"}]'::jsonb),
    ('efc5d816-988a-4e81-9cbb-29be23f75771'::uuid, 'card_description', 'A 2nd-century shrine to the goddess Minerva carved into a quarry face. It is the only rock-cut Roman shrine in all of Western Europe that remains in its original location.', 'Carved into a sandstone quarry face in the early 2nd century, Minerva''s Shrine in Chester is considered the only monument of its type in western Europe still in its original location.', 'teaser-card-s011:efc5d816-988a-4e81-9cbb-29be23f75771:card_description', 'teaser-card-s011 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'de0f796efc0a209a2372f1acd34b5b758eaf54f61f44e4d6bb19f1706fc8e8b8|476a1222a00d3dfa28f5f4b3350b866e1365ea0411f81afb837f0eb50fa5bd02|476a1222a00d3dfa28f5f4b3350b866e1365ea0411f81afb837f0eb50fa5bd02', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Carved into a sandstone quarry face in the early 2nd century, Minerva''s Shrine in Chester is considered the only monument of its type in western Europe still in its original location."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the shrine is carved into a sandstone quarry face [S2]; it dates from the early 2nd century [S2]; it is in Chester [S1]; it is considered the only monument of its type in western Europe still in its original location [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Minerva''s Shrine is a Roman shrine to the goddess Minerva in Chester, England [SUPPORTED: https://en.wikipedia.org/wiki/Minerva%27s_Shrine,_Chester]; The shrine dates from the early 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Minerva%27s_Shrine,_Chester]; The shrine is carved into the face of a sandstone quarry [SUPPORTED: https://en.wikipedia.org/wiki/Minerva%27s_Shrine,_Chester]; It is considered the only monument of its type in western Europe still in its original location [SUPPORTED: https://en.wikipedia.org/wiki/Minerva%27s_Shrine,_Chester]"}]'::jsonb),
    ('f0ac24b0-babb-4e1d-9d56-423ad12d6206'::uuid, 'card_description', 'A Minoan palace rebuilt around 1600 BC after an earlier version, destroyed along with other Minoan centers around 1450 BC. Its harbor made it a key hub for eastern trade.', 'Through Zakros, a Minoan site on the eastern coast of Crete, runs the Ravine of the Dead, named for the numerous burials found in caves along its walls. Finds here included a winepress.', 'teaser-card-s011:f0ac24b0-babb-4e1d-9d56-423ad12d6206:card_description', 'teaser-card-s011 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '7fbd0e5fb123e65af5ecef2504cb57656441775cd65d62f0343a477db76afbf9|8d2a763d15d63c69ba1bf0e48a6cfbe6c002bf288a1a82bebfa7d5799829186e|8d2a763d15d63c69ba1bf0e48a6cfbe6c002bf288a1a82bebfa7d5799829186e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Through Zakros, a Minoan site on the eastern coast of Crete, runs the Ravine of the Dead, named for the numerous burials found in caves along its walls. Finds here included a winepress."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Zakros is a Minoan site [S1]; it is on the eastern coast of Crete [S1]; the Ravine of the Dead runs through the site [S4]; the ravine is named for the numerous burials found in the caves along its walls [S4]; finds at the site included a winepress [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Zakros is a Minoan archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Zakros]; Zakros is on the eastern coast of Crete [SUPPORTED: https://en.wikipedia.org/wiki/Zakros]; The Ravine of the Dead runs through the Zakros site [SUPPORTED: https://en.wikipedia.org/wiki/Zakros]; The Ravine of the Dead is named for the numerous burials found in caves along its walls [SUPPORTED: https://en.wikipedia.org/wiki/Zakros]; Finds at Zakros included a winepress [SUPPORTED: https://en.wikipedia.org/wiki/Zakros]"}]'::jsonb),
    ('f0b4765f-f0ab-46bf-bfb0-900cd3914323'::uuid, 'card_description', 'Covering 11 hectares near Great Witley, dating from around 1200 BC. Its single rampart extends roughly 600 meters east to west, with inturned entrance ramparts forming a defensive corridor.', 'Overlooking the River Teme, the Iron Age hillfort on Woodbury Hill is called Owen Glendower''s Camp: in 1405 the army of Owain Glyndŵr faced that of King Henry IV of England here.', 'teaser-card-s011:f0b4765f-f0ab-46bf-bfb0-900cd3914323:card_description', 'teaser-card-s011 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'dc4911a8f20f0b664691fc9a10215828cedf145b8ff251355a923ba85fd6dc25|59dd8b69cee18de7cbc2e97d3d57798076d9103cc4c858f1ec2b98f701566549|59dd8b69cee18de7cbc2e97d3d57798076d9103cc4c858f1ec2b98f701566549', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Overlooking the River Teme, the Iron Age hillfort on Woodbury Hill is called Owen Glendower''s Camp: in 1405 the army of Owain Glyndŵr faced that of King Henry IV of England here."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the hill overlooks the River Teme [S3]; Woodbury Hill has an Iron Age hillfort [S2]; the fort is called Owen Glendower''s Camp [S7]; in 1405 the army of Owain Glyndwr faced the army of King Henry IV of England there (a standoff) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Woodbury Hill in Worcestershire, England is the site of an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill]; Woodbury Hill is in Worcestershire, England [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill]; The hill overlooks the River Teme [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill]; The fort is called Owen Glendower''s Camp [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill]; In 1405 the army of Owain Glyndwr faced the army of King Henry IV of England here (a standoff) [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Hill]"}]'::jsonb),
    ('f0b786ae-17e0-4ce1-bfdc-c9184e5473a3'::uuid, 'card_description', 'On 27 August 1937, excavators discovered the right femur diaphysis, measuring around 25 cm in length, of an archaic hominin in the cave.', 'In a cave of the Swabian Jura, Hohlenstein-Stadel gave up the Löwenmensch, a small ivory statue among the oldest figurative art ever found, and a femur that DNA showed was a Neanderthal''s.', 'teaser-card-s011:f0b786ae-17e0-4ce1-bfdc-c9184e5473a3:card_description', 'teaser-card-s011 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '4f74df0de64a3209b39b8396b8a7948afc906eab79c1d244ed83170da37e2580|7503c6296a288812a82cc1b865a050e136ace9d18efb79c43442b4ac52558000|7503c6296a288812a82cc1b865a050e136ace9d18efb79c43442b4ac52558000', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In a cave of the Swabian Jura, Hohlenstein-Stadel gave up the Löwenmensch, a small ivory statue among the oldest figurative art ever found, and a femur that DNA showed was a Neanderthal''s."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hohlenstein-Stadel is a cave in the Swabian Jura [S1]; the cave yielded the Löwenmensch, a small ivory statue [S2]; the Löwenmensch is among the oldest pieces of figurative art ever found [S2]; a femur was found in the cave [S4]; DNA (mtDNA sequencing) showed the femur belonged to a Neanderthal [S6, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hohlenstein-Stadel is a cave in the Swabian Jura (Germany) [SUPPORTED: https://en.wikipedia.org/wiki/Hohlenstein-Stadel]; The cave yielded the Löwenmensch, a small ivory statue [SUPPORTED: https://en.wikipedia.org/wiki/Hohlenstein-Stadel]; The Löwenmensch is among the oldest figurative art ever found [SUPPORTED: https://en.wikipedia.org/wiki/Hohlenstein-Stadel]; A femur was found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Hohlenstein-Stadel]; DNA showed the femur was a Neanderthal''s [SUPPORTED: https://en.wikipedia.org/wiki/Hohlenstein-Stadel]"}]'::jsonb),
    ('f1a0b11e-e382-42dd-bfdd-4116409af9ca'::uuid, 'card_description', 'Early Christian catacombs at Gudja with carvings so unusual they provoke debate: some historians classify them as paleochristian; others question whether the Christian markers are conclusive.', 'Dug into Globigerina Limestone, the Ħal Resqun Catacombs open through an arched entrance carved with a peacock and a peahen feeding a chick, its doorway flanked by two engraved columns.', 'teaser-card-s011:f1a0b11e-e382-42dd-bfdd-4116409af9ca:card_description', 'teaser-card-s011 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '35890d71aa478fcaf91a122eebcff04098475fae4689419ceaa56c810ed396db|5714f6a950e50be480eeca906f6eb60b49ef669941aed7577bd56a7aaddd38c7|5714f6a950e50be480eeca906f6eb60b49ef669941aed7577bd56a7aaddd38c7', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dug into Globigerina Limestone, the Ħal Resqun Catacombs open through an arched entrance carved with a peacock and a peahen feeding a chick, its doorway flanked by two engraved columns."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the catacombs are dug into Globigerina Limestone [S2]; the entrance is arched [S4]; the entrance is carved with a peacock and a peahen feeding a chick [S4]; the doorway is flanked by two engraved columns [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Ħal Resqun Catacombs are early Christian catacombs (hypogea) in Malta [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6al_Resqun_Catacombs]; The catacombs are dug into Globigerina Limestone [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6al_Resqun_Catacombs]; The catacombs are entered through an arched entrance [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6al_Resqun_Catacombs]; The entrance is carved with a peacock and a peahen feeding a chick [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6al_Resqun_Catacombs]; The doorway is flanked by two engraved columns [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A6al_Resqun_Catacombs]"}]'::jsonb),
    ('f2041141-c82a-4e04-a6e6-d7d2e29f4ea5'::uuid, 'card_description', 'Funnelbeaker culture passage grave, built 3500–2800 BC. Reused in the Bronze or Iron Age, excavated in 1969–70, then physically relocated to its current site for long-term preservation.', 'A Neolithic burial of the Funnelbeaker culture, the Schalkholz Passage Grave was archaeologically investigated in 1969 and 1970, then moved to Heide. In 2021 it went back to Schalkholz.', 'teaser-card-s011:f2041141-c82a-4e04-a6e6-d7d2e29f4ea5:card_description', 'teaser-card-s011 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '117147fcc5fba106429278ba326fc97d006e9a962e8ee5eeddea5902249b450b|1f4de06ef5981f2c1afbaaa431e658e7748b4ff239d3ed46016e520dd2186f95|1f4de06ef5981f2c1afbaaa431e658e7748b4ff239d3ed46016e520dd2186f95', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "A Neolithic burial of the Funnelbeaker culture, the Schalkholz Passage Grave was archaeologically investigated in 1969 and 1970, then moved to Heide. In 2021 it went back to Schalkholz."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Schalkholz Passage Grave is a Neolithic burial site [S1]; it belongs to the Funnelbeaker culture [S1]; it was archaeologically investigated in 1969 and 1970 [S4]; afterwards it was moved to Heide [S4]; in 2021 it was moved back to Schalkholz [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Schalkholz Passage Grave is a megalithic burial site (a grave) at Schalkholz, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Schalkholz_Passage_Grave]; The grave is a passage grave [SUPPORTED: https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Schalkholz-Vierth]; It is a Neolithic burial [SUPPORTED: https://en.wikipedia.org/wiki/Schalkholz_Passage_Grave]; It belongs to the Funnelbeaker culture [SUPPORTED: https://en.wikipedia.org/wiki/Schalkholz_Passage_Grave]; It was archaeologically investigated in 1969 and 1970 [SUPPORTED: https://en.wikipedia.org/wiki/Schalkholz_Passage_Grave]; After the investigation it was moved to Heide [SUPPORTED: https://en.wikipedia.org/wiki/Schalkholz_Passage_Grave]; In 2021 it was moved back to Schalkholz [SUPPORTED: https://en.wikipedia.org/wiki/Schalkholz_Passage_Grave]"}]'::jsonb),
    ('f2753198-6435-4d5a-a137-7603ed289edc'::uuid, 'card_description', 'The earliest structures found at Altun Ha, found in Zone C, are two round platforms that date to about BC 900−800.', 'Over 800 pieces of jade have been recovered at Altun Ha, where the Temple of the Masonry Altars is 16 metres high. By the beginning of the eleventh century, the site was abandoned.', 'teaser-card-s011:f2753198-6435-4d5a-a137-7603ed289edc:card_description', 'teaser-card-s011 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '0c155a9558210d7497dea25aecad6ba95b2f126ebd91f8485d9ac1a9a254d3f8|9b3fa7759f71f9371ba68ee6a834fe202e9623ceb378036f76ee96d1376eb28d|9b3fa7759f71f9371ba68ee6a834fe202e9623ceb378036f76ee96d1376eb28d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Over 800 pieces of jade have been recovered at Altun Ha, where the Temple of the Masonry Altars is 16 metres high. By the beginning of the eleventh century, the site was abandoned."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "over 800 pieces of jade have been recovered at Altun Ha [S7]; the Temple of the Masonry Altars is at Altun Ha [S3]; the Temple of the Masonry Altars is 16 metres high [S3]; by the beginning of the eleventh century the site was abandoned [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Altun Ha is the ruins of an ancient Maya city in Belize [SUPPORTED: https://en.wikipedia.org/wiki/Altun_Ha]; Over 800 pieces of jade have been recovered at Altun Ha [SUPPORTED: https://en.wikipedia.org/wiki/Altun_Ha]; The Temple of the Masonry Altars at Altun Ha is 16 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Altun_Ha]; By the beginning of the eleventh century the site was abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Altun_Ha]"}]'::jsonb),
    ('f31a9f3d-cf05-4d57-8e67-7c747035df86'::uuid, 'card_description', 'A granite Roman bridge from the 1st century BC, part of the Vía de la Plata trade route. It spans a tributary that still flows beneath its original arches.', 'In Mérida, the granite Albarregas Roman bridge carries the Vía de la Plata across the river Albarregas, a tributary of the Guadiana, parallel to the nearby Acueducto de los Milagros.', 'teaser-card-s011:f31a9f3d-cf05-4d57-8e67-7c747035df86:card_description', 'teaser-card-s011 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'd53bd35f84645fe1ba9df6202948a4042d73f8fc5b86512932ed2ea3b27be7dc|a53b3312bc39d7971d94760f126a8cda2edcbeb7f7de59cfb26e08674c8cdf9c|a53b3312bc39d7971d94760f126a8cda2edcbeb7f7de59cfb26e08674c8cdf9c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Mérida, the granite Albarregas Roman bridge carries the Vía de la Plata across the river Albarregas, a tributary of the Guadiana, parallel to the nearby Acueducto de los Milagros."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the bridge is in Mérida [S1]; the bridge is built of granite [S2]; it crosses the river Albarregas [S2]; the Albarregas is a tributary of the Guadiana [S2]; the bridge is part of the Vía de la Plata [S3]; it runs parallel to the nearby Acueducto de los Milagros [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Albarregas Roman bridge is a Roman bridge [SUPPORTED: https://en.wikipedia.org/wiki/Albarregas_Roman_bridge]; The bridge is in Mérida, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Albarregas_Roman_bridge]; The bridge is built of granite [SUPPORTED: https://en.wikipedia.org/wiki/Albarregas_Roman_bridge]; The bridge crosses the river Albarregas [SUPPORTED: https://en.wikipedia.org/wiki/Albarregas_Roman_bridge]; The river Albarregas is a tributary of the Guadiana [SUPPORTED: https://en.wikipedia.org/wiki/Albarregas_Roman_bridge]; The bridge carries the Vía de la Plata [SUPPORTED: https://en.wikipedia.org/wiki/Albarregas_Roman_bridge]; The bridge runs parallel to the nearby Acueducto de los Milagros [SUPPORTED: https://en.wikipedia.org/wiki/Albarregas_Roman_bridge]"}]'::jsonb),
    ('f3470fb3-320f-4660-b9e0-ed338741f464'::uuid, 'card_description', 'The site of Hannibal''s greatest victory: in 216 BC he encircled and destroyed a Roman army of 80,000. The battle remains a textbook example of double envelopment.', 'On the hill of Monte di Canne in Apulia, the remains of a Roman town still lie at Cannae, an ancient village that later became a municipium and, in the Middle Ages, a bishopric.', 'teaser-card-s011:f3470fb3-320f-4660-b9e0-ed338741f464:card_description', 'teaser-card-s011 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '2d7e05ad06fb21ea2d7d9718bac970eb6ebb5d212cc782079e4d1e9d3268aa5b|011c971ad437f55d15084a3ddc354354f7ba860bc03b3fa562708222ca8d9b50|011c971ad437f55d15084a3ddc354354f7ba860bc03b3fa562708222ca8d9b50', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the hill of Monte di Canne in Apulia, the remains of a Roman town still lie at Cannae, an ancient village that later became a municipium and, in the Middle Ages, a bishopric."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Cannae is an ancient village in Apulia [S1]; remains of a Roman town still exist on the hill known as Monte di Canne [S2]; the place later became a municipium [S2]; in the Middle Ages it became a bishopric [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Cannae is an ancient village in Apulia (the site, central claim: a settlement/town in the Apulia region of Italy) [SUPPORTED: https://en.wikipedia.org/wiki/Cannae]; The remains of a Roman town still exist at Cannae on the hill known as Monte di Canne [SUPPORTED: https://en.wikipedia.org/wiki/Cannae]; The place later became a municipium [SUPPORTED: https://en.wikipedia.org/wiki/Cannae]; In the Middle Ages Cannae became a bishopric [SUPPORTED: https://en.wikipedia.org/wiki/Cannae]"}]'::jsonb),
    ('f3df5faa-2f56-492b-b526-a229f971d12a'::uuid, 'card_description', 'An Inca administrative center with a large plaza where sacrificial ceremonies were performed. A Sun Temple and Moon Temple flanked the central square.', 'Atop the Ushnu of Vilcashuamán, a truncated pyramid on an Inca plaza of sacrifices, sits the carved stone called the Seat of the Inca, once covered with gold leaf, says Cieza de León.', 'teaser-card-s011:f3df5faa-2f56-492b-b526-a229f971d12a:card_description', 'teaser-card-s011 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'bc30a16365f4f1871adec877acd5fefd09caddaf5085d2a523d00e4afa8c9d05|069fe5156bb11077fddc094bc0d0701ff18eb644b71ce349fdfd29116b78d312|069fe5156bb11077fddc094bc0d0701ff18eb644b71ce349fdfd29116b78d312', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Atop the Ushnu of Vilcashuamán, a truncated pyramid on an Inca plaza of sacrifices, sits the carved stone called the Seat of the Inca, once covered with gold leaf, says Cieza de León."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Vilcashuamán was an Inca city [S1]; the Ushnu is a truncated pyramid [S4]; the city stood around a plaza where sacrifice ceremonies were performed [S2]; the Ushnu is one of the buildings at that plaza [S3]; a large carved stone on the Ushnu''s upper platform is called the Seat of the Inca [S5]; according to Cieza de León the seat was once covered with gold leaf [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Vilcashuamán is an Inca administrative center (an Inca city and archaeological site) in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; Vilcashuamán is in Peru (an ancient archaeological site in the Andes) [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; The city of Vilcashuamán was built around a large Inca plaza [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; The plaza was a place where ceremonies involving sacrifices were performed [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; The Ushnu stands at this plaza (one of the city''s two most important buildings around it) [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; The Ushnu of Vilcashuamán is a truncated pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; On the upper platform (atop) of the Ushnu is a large stone with carvings [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; The carved stone atop the Ushnu is called the Seat of the Inca [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; The Seat of the Inca was once covered with gold leaf [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]; The gold-leaf covering is reported by the chronicler Cieza de Leon [SUPPORTED: https://en.wikipedia.org/wiki/Vilcashuam%C3%A1n]"}]'::jsonb),
    ('f4188020-1870-4ba4-ad15-f162b33e1605'::uuid, 'card_description', 'Iron Age bank-and-ditch enclosure dated 1200 BC–1st century AD in West Somerset. Almost square in plan with rounded corners, covering just 0.28 hectares — small, defensible, and little excavated.', 'Approximately 2 miles west of Winsford in Somerset, the Iron Age hill fort of Road Castle is a bank and ditch almost square in plan, with rounded corners, covering approximately 0.7 acres.', 'teaser-card-s011:f4188020-1870-4ba4-ad15-f162b33e1605:card_description', 'teaser-card-s011 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '751548f121878fa35e602ab198b201679f9dbcddeac0740a5aa0074452debf5c|cbbbd660aca7690ad2fe7bf7093dc7c2459d5782739eda3c9599267214a69d93|cbbbd660aca7690ad2fe7bf7093dc7c2459d5782739eda3c9599267214a69d93', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Approximately 2 miles west of Winsford in Somerset, the Iron Age hill fort of Road Castle is a bank and ditch almost square in plan, with rounded corners, covering approximately 0.7 acres."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Road Castle lies approximately 2 miles west of Winsford [S2]; it is in Somerset [S1]; it is an Iron Age hill fort [S1, S2]; it is a bank and ditch [S1]; it is almost square in plan with rounded corners [S3]; it covers approximately 0.7 acres [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Road Castle is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]; Road Castle is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]; Road Castle consists of a bank and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]; Road Castle is in Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]; Road Castle lies approximately 2 miles west of Winsford [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]; The earthwork is almost square in plan [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]; The earthwork has rounded corners [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]; It covers approximately 0.7 acres [SUPPORTED: https://en.wikipedia.org/wiki/Road_Castle]"}]'::jsonb),
    ('f452eac9-a36e-4315-9dd3-58c2c382837f'::uuid, 'card_description', 'Around 1200 BC. A Bronze Age tomb discovered in 1979 during refugee settlement construction - now buried beneath a Larnaca supermarket, its unexcavated layers sealed under the city block.', 'While a refugee settlement rose in Larnaca, a tomb came to light on March 22, 1979; that year 63 tombs were excavated at the Mnemata Site, a cemetery from the Iron Age to Roman times.', 'teaser-card-s011:f452eac9-a36e-4315-9dd3-58c2c382837f:card_description', 'teaser-card-s011 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'f2c5bf443ddf410247130849634d378b7a4e896e5885559282ca1ce5426ab086|f97d2c1fcf7d7fad703d90466d13c34c165e25f2d297cafb04f85608bc5b2a7f|f97d2c1fcf7d7fad703d90466d13c34c165e25f2d297cafb04f85608bc5b2a7f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "While a refugee settlement rose in Larnaca, a tomb came to light on March 22, 1979; that year 63 tombs were excavated at the Mnemata Site, a cemetery from the Iron Age to Roman times."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "a refugee settlement was being built in Larnaca [S1, S3]; a tomb was discovered on March 22, 1979 [S3]; 63 tombs were excavated at the site in 1979 [S4]; the site was a cemetery from the Iron Age to Roman times [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Mnemata Site is an archaeological site in Larnaca, Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Mnemata_Site]; The Mnemata Site is a cemetery (also known as the Agios Georgios cemetery) [SUPPORTED: https://en.wikipedia.org/wiki/Mnemata_Site]; The site was used as a cemetery from the Iron Age to Roman times [SUPPORTED: https://en.wikipedia.org/wiki/Mnemata_Site]; A refugee settlement was being built in Larnaca when the tomb was found (Agios Georgios refugee settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Mnemata_Site]; A tomb was discovered on March 22, 1979 [SUPPORTED: https://en.wikipedia.org/wiki/Mnemata_Site]; In 1979, 63 tombs were excavated at the site [SUPPORTED: https://en.wikipedia.org/wiki/Mnemata_Site]"}]'::jsonb),
    ('f4f0c9af-1941-4d22-9513-4ec574590a9d'::uuid, 'card_description', NULL, 'Among the Fortifications of London, the first defensive wall was built by the Romans around 200 AD. In use for over 1,000 years, it defended the city against raiding Saxons in 457.', 'teaser-card-s011:f4f0c9af-1941-4d22-9513-4ec574590a9d:card_description', 'teaser-card-s011 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '54e128fdaca7ed8372428018c47f8b9d1fccbcd02488677de68a5d3a0bd19d41|f5a68d00e73c24f92ca87128382c0f53968630d1c9d7f68870dad271c917ed29|f5a68d00e73c24f92ca87128382c0f53968630d1c9d7f68870dad271c917ed29', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Among the Fortifications of London, the first defensive wall was built by the Romans around 200 AD. In use for over 1,000 years, it defended the city against raiding Saxons in 457."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "London''s first defensive wall was built by the Romans [S2]; it was built around 200 AD [S2]; the wall remained in use as a fortification for over 1,000 years [S4]; it defended London against raiding Saxons in 457 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Fortifications of London are the defences of London (city walls, gates, castles), in England [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_London]; London''s first defensive wall was built by the Romans around 200 AD [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_London]; The wall was in use as a fortification for over 1,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_London]; In 457 the wall defended London against raiding Saxons [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('f634e2ff-366e-49f1-be74-ac930ba5bc02'::uuid, 'card_description', 'The Menhir de Champ-Dolent is a menhir, or upright standing stone, located in a field outside the town of Dol-de-Bretagne.', 'In a field south of Dol-de-Bretagne rises the Menhir de Champ-Dolent, around 9.4 metres high, the second largest standing stone in Brittany. A cross was once placed on its top.', 'teaser-card-s011:f634e2ff-366e-49f1-be74-ac930ba5bc02:card_description', 'teaser-card-s011 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'f84bac2a7a7c3dc1c8a33bdc929de64a4e558e3262bad0213e8e93588d5224b5|62625c23497b1c056664f33c5608419b5f68535f286045d03b85fdfe441651fc|62625c23497b1c056664f33c5608419b5f68535f286045d03b85fdfe441651fc', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In a field south of Dol-de-Bretagne rises the Menhir de Champ-Dolent, around 9.4 metres high, the second largest standing stone in Brittany. A cross was once placed on its top."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the menhir stands in a field [S1]; it lies south of Dol-de-Bretagne [S3]; it rises as an upright standing stone [S1]; it is around 9.4 metres high [S2]; it is the second largest standing stone in Brittany [S2]; a cross was once placed on its top [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Menhir de Champ-Dolent is a menhir, an upright standing stone (the central claim: a standing stone) [SUPPORTED: https://en.wikipedia.org/wiki/Menhir_de_Champ-Dolent]; The menhir stands in a field [SUPPORTED: https://en.wikipedia.org/wiki/Menhir_de_Champ-Dolent]; The menhir stands south of Dol-de-Bretagne [SUPPORTED: https://en.wikipedia.org/wiki/Menhir_de_Champ-Dolent]; The menhir is around 9.4 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Menhir_de_Champ-Dolent]; It is the second largest standing stone [SUPPORTED: https://en.wikipedia.org/wiki/Menhir_de_Champ-Dolent]; The ranking is within Brittany [SUPPORTED: https://en.wikipedia.org/wiki/Menhir_de_Champ-Dolent]; A cross was once placed on its top [SUPPORTED: https://en.wikipedia.org/wiki/Menhir_de_Champ-Dolent]"}]'::jsonb),
    ('f6f190b6-7c0b-4cf5-8ceb-cf9ec567997d'::uuid, 'card_description', 'The locality of Abusir took its turn as the focus of the prestigious western burial rites operating out of the then-capital of Memphis during the Old Kingdom Fifth Dynasty.', 'On the desert plateau between Giza and Saqqara lies Abusir, an elite cemetery of ancient Memphis, and the origin of the largest find of Old Kingdom papyri to date.', 'teaser-card-s011:f6f190b6-7c0b-4cf5-8ceb-cf9ec567997d:card_description', 'teaser-card-s011 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', '6a71d140a3c45121607363aec4633815f51cc04390c98cac2f3caccceb8ef180|2f3c08e83b1fe9822fd444de59164e8bc59e54d31e4534e8ba404418ce993ad6|2f3c08e83b1fe9822fd444de59164e8bc59e54d31e4534e8ba404418ce993ad6', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the desert plateau between Giza and Saqqara lies Abusir, an elite cemetery of ancient Memphis, and the origin of the largest find of Old Kingdom papyri to date."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Abusir lies on the desert plateau [S1]; it lies between Giza (to the north) and Saqqara (to the south) [S1]; Abusir is an elite cemetery of ancient Memphis [S1]; Abusir is the origin of the largest find of Old Kingdom papyri to date [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Abusir is a cemetery, an ancient Egyptian pyramid complex and necropolis (the central claim: an elite cemetery) [SUPPORTED: https://en.wikipedia.org/wiki/Abusir]; The cemetery belongs to ancient Memphis [SUPPORTED: https://en.wikipedia.org/wiki/Abusir]; Abusir lies on a desert plateau [SUPPORTED: https://en.wikipedia.org/wiki/Abusir]; Abusir lies between Giza and Saqqara [SUPPORTED: https://en.wikipedia.org/wiki/Abusir]; Abusir was the origin of the largest find of Old Kingdom papyri to date [SUPPORTED: https://en.wikipedia.org/wiki/Abusir]"}]'::jsonb),
    ('f7f2dac5-0f0a-4cbd-8ac0-c2f1f42311ca'::uuid, 'card_description', 'A cave occupied by Neanderthals until as late as 39,000 years ago, one of their last known habitats. It has been nicknamed the "last house of the Neanderthals."', 'On a hillock on the northern slopes of Suva Planina, at 330 m, Pešturina is one of three caves in a row. Excavations since 2006 have brought Middle and Upper Paleolithic artifacts to light.', 'teaser-card-s011:f7f2dac5-0f0a-4cbd-8ac0-c2f1f42311ca:card_description', 'teaser-card-s011 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '16fa50b2913c37c016264012f5df61190ef1c7e69d52ed55a01d041a4818bbaa|684f25e032c7a5e46021910d1654d70f3e0ee652a835ff7677bdedc629d3450f|684f25e032c7a5e46021910d1654d70f3e0ee652a835ff7677bdedc629d3450f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a hillock on the northern slopes of Suva Planina, at 330 m, Pešturina is one of three caves in a row. Excavations since 2006 have brought Middle and Upper Paleolithic artifacts to light."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pešturina lies on a hillock [S4]; the hillock is on the northern slopes of Suva Planina [S4]; the altitude is 330 m [S4]; Pešturina is one of three caves in a row [S5]; excavations began in 2006 [S3]; the excavations brought Middle and Upper Paleolithic artifacts to light [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pešturina is a cave (the central claim: a cave, in Serbia) [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]; The cave is located on a hillock [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]; The hillock is on the northern slopes of Suva Planina [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]; The cave lies at 330 m altitude [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]; Pešturina is one of three caves in a row [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]; Excavations began in 2006 (excavations since 2006) [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]; Excavations brought Middle Paleolithic artifacts to light [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]; Excavations brought Upper Paleolithic artifacts to light [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C5%A1turina]"}]'::jsonb),
    ('f7fec312-2d2f-4dc7-87dd-a425ddbfa454'::uuid, 'card_description', 'Pre-Pottery Neolithic B settlement near Limassol, 9th–8th millennium BC. Cattle were present early on but died out by the 8th millennium — gone entirely until a separate later reintroduction.', 'On a low plateau near Limassol, Shillourokambos kept circular wattle and daub structures, around 300 blades of Anatolian obsidian, and signs of cattle from a Neolithic without pottery.', 'teaser-card-s011:f7fec312-2d2f-4dc7-87dd-a425ddbfa454:card_description', 'teaser-card-s011 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'c7ca80ecce8c0e6a195f53214bd924becf56b3223a7640914bec50b07b60bc01|77483e1639c4cbbf13dd0ffda345036275202d2e3ea2e696dbf96471500d2e68|77483e1639c4cbbf13dd0ffda345036275202d2e3ea2e696dbf96471500d2e68', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a low plateau near Limassol, Shillourokambos kept circular wattle and daub structures, around 300 blades of Anatolian obsidian, and signs of cattle from a Neolithic without pottery."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies on a low plateau [S2]; the site lies near Limassol [S1]; it had circular wattle and daub structures [S5]; around 300 blades of Anatolian obsidian were found [S6]; the site shows signs (the presence) of cattle [S7]; the period is a Neolithic without pottery (aceramic) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Shillourokambos is a Neolithic settlement site in Cyprus (the central claim: a settlement, a Pre-Pottery Neolithic B site) [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]; The site is near Limassol [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]; The site is on a low plateau [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]; The site had circular wattle and daub structures [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]; Around 300 blades were found [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]; The blades are of Anatolian obsidian [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]; The site shows signs (bones) of cattle [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]; The Neolithic phase was without pottery (aceramic / Pre-Pottery) [SUPPORTED: https://en.wikipedia.org/wiki/Shillourokambos]"}]'::jsonb),
    ('f82d4a70-4581-4e06-858a-d52019ecbd0f'::uuid, 'card_description', 'The site was sporadically inhabited by the Maya since its initial settlement during the Middle Preclassic.', 'On a peninsula in Lake Salpeten, Zacpeten was abandoned and resettled more than once. Then the Kowoj Maya came from Mayapan and stayed free of Spanish rule until late into the 17th century.', 'teaser-card-s011:f82d4a70-4581-4e06-858a-d52019ecbd0f:card_description', 'teaser-card-s011 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'e1cfdbd491aeded3786bb261e628a6514174d5b0b3472af9dd3417daab8a7e66|9fa02c22699166bee1fb61831f870b1acd352201c8beebed33958c11098ab2ee|9fa02c22699166bee1fb61831f870b1acd352201c8beebed33958c11098ab2ee', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a peninsula in Lake Salpeten, Zacpeten was abandoned and resettled more than once. Then the Kowoj Maya came from Mayapan and stayed free of Spanish rule until late into the 17th century."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Zacpeten lies on a peninsula in Lake Salpeten [S2]; the site was abandoned and resettled more than once [S3, S4, S5]; afterwards the Kowoj Maya came to the site [S5, S6]; the Kowoj Maya came from Mayapan [S5, S6]; they stayed independent of Spanish rule until late into the 17th century [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Zacpeten is a Maya archaeological site (a settlement with ceremonial and residential groups) in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; The site is on a peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; The peninsula is in Lake Salpeten [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; The site was abandoned and resettled (first time: abandoned in Late Preclassic and Early Classic, resettled from the Late Classic) [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; It was abandoned and resettled more than once (abandoned again, then reoccupied in the Late Postclassic) [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; The Kowoj Maya are the people who then reoccupied the site [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; The Kowoj Maya came from Mayapan [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; The settlement stayed free of Spanish rule (independent of Spanish domination) [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]; The independence lasted until late into the 17th century [SUPPORTED: https://en.wikipedia.org/wiki/Zacpeten]"}]'::jsonb),
    ('f8571940-a590-4f5f-a2bc-c57efd1853b7'::uuid, 'card_description', 'The present bath ruins constitute about one-third of a massive bath complex that is believed to have been constructed around the beginning of the 3rd century.', 'In the heart of Paris, the vaulted frigidarium of the Thermes de Cluny survives, its consoles carved like ships'' prows: the baths are believed to have been built by a guild of boatmen.', 'teaser-card-s011:f8571940-a590-4f5f-a2bc-c57efd1853b7:card_description', 'teaser-card-s011 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '4669f1d93bf4538c86fa9284c68b9dc3c23399cfc38438616ce16c58995bb9ef|1aa970bb43dfd9289a30ae082eb619a34d034bbfe5983a584bf73517f6e04f09|1aa970bb43dfd9289a30ae082eb619a34d034bbfe5983a584bf73517f6e04f09', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the heart of Paris, the vaulted frigidarium of the Thermes de Cluny survives, its consoles carved like ships'' prows: the baths are believed to have been built by a guild of boatmen."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Thermes de Cluny lie in the heart of Paris [S1]; the frigidarium survives with vaults [S3]; the consoles are carved like ships'' prows [S3, S4]; the baths are believed to have been built by a guild of boatmen [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Thermes de Cluny are the ruins of Gallo-Roman baths in the heart of Paris [SUPPORTED: https://en.wikipedia.org/wiki/Thermes_de_Cluny]; The frigidarium of the baths survives, with intact Gallo-Roman vaults [SUPPORTED: https://en.wikipedia.org/wiki/Thermes_de_Cluny]; The frigidarium has a vaulted ceiling 14.5 metres high, still standing [SUPPORTED: https://archeologie.culture.gouv.fr/paris/en/frigidarium]; The consoles of the frigidarium vault are carved like ships'' prows [SUPPORTED: https://en.wikipedia.org/wiki/Thermes_de_Cluny]; The baths are believed to have been built by a guild of boatmen [SUPPORTED: https://en.wikipedia.org/wiki/Thermes_de_Cluny]"}]'::jsonb),
    ('f9e7abcd-b8a2-4844-8145-4a29f19568e2'::uuid, 'card_description', 'A forest clearing with about 50 upright megaliths, many over 2.5 metres tall. These Bronze Age stones once numbered far more — neighboring sites have lost theirs to farm clearance.', 'At Louisenlund, megaliths stand alone or in small groups, one of Denmark''s largest collections. The site has not been archeologically investigated, so why they were raised is not known.', 'teaser-card-s011:f9e7abcd-b8a2-4844-8145-4a29f19568e2:card_description', 'teaser-card-s011 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '2d08488256c87199a5e350bf2d164bccd76224bf53ddc624652ba0cb007f61f1|26cecb1f66fa5d40bbf7a8d4d4490460bb21a770b0a9bc5cf87a352a250c8c51|26cecb1f66fa5d40bbf7a8d4d4490460bb21a770b0a9bc5cf87a352a250c8c51', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Louisenlund, megaliths stand alone or in small groups, one of Denmark''s largest collections. The site has not been archeologically investigated, so why they were raised is not known."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "megaliths stand at Louisenlund [S1]; the stones stand alone or in small groups [S2]; it is one of Denmark''s largest collections of megaliths [S1]; the site has not been archeologically investigated [S3]; why the stones were raised there is not known [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Louisenlund, on the Danish island of Bornholm, is a site of megaliths (standing stones) [SUPPORTED: https://lex.dk/Louisenlund_-_samling_af_bautasten_p%C3%A5_Bornholm]; It is one of Denmark''s largest collections of megaliths [SUPPORTED: https://en.wikipedia.org/wiki/Louisenlund_(Bornholm)]; The megaliths stand alone or in small groups [SUPPORTED: https://en.wikipedia.org/wiki/Louisenlund_(Bornholm)]; The site has not been archaeologically investigated [SUPPORTED: https://en.wikipedia.org/wiki/Louisenlund_(Bornholm)]; It is not known why the stones were raised there [SUPPORTED: https://en.wikipedia.org/wiki/Louisenlund_(Bornholm)]"}]'::jsonb),
    ('faf09f30-a927-4d6b-9fd9-14e1ab1b7c81'::uuid, 'card_description', 'An ancient city-state mentioned by Homer in the Iliad as ruled by Protesilaus. It sits on the Pagasaean Gulf, inhabited since the 6th millennium BC.', 'Barely known in historical times, Pyrasus survives in a small fragment of an old inscription bearing its name, and in the arm of a large statue attributed to Demeter, found in 1965.', 'teaser-card-s011:faf09f30-a927-4d6b-9fd9-14e1ab1b7c81:card_description', 'teaser-card-s011 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'd6de53286a2be9b43c10dd905e113d3efb5f697b243316c0a4f8219a13ec8920|39b47c71b50b901f13feaf298906e1bbea0cb93dd995c2cb46ad23dd6c193f78|39b47c71b50b901f13feaf298906e1bbea0cb93dd995c2cb46ad23dd6c193f78', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Barely known in historical times, Pyrasus survives in a small fragment of an old inscription bearing its name, and in the arm of a large statue attributed to Demeter, found in 1965."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pyrasus is barely known in historical times [S4]; a small fragment of an old inscription bearing the name Pyrasus was found [S6]; an arm of a large statue was found, attributed to Demeter [S5]; the arm came to light in 1965 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pyrasus was an ancient Greek town (polis) in Thessaly [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]; Pyrasus is barely known in historical times [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]; Archaeological remains of Pyrasus are scarce [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]; A small fragment of an old inscription (epigraph) was found [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]; The inscription fragment bears the name Pyrasus (found in the remains of Basilica D) [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]; The arm of a large statue was found at Pyrasus [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]; The statue arm came to light in 1965 [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]; The statue arm is attributed to Demeter [SUPPORTED: https://en.wikipedia.org/wiki/Pyrasus]"}]'::jsonb),
    ('fb877d92-953a-4dba-af74-64ac1330e47e'::uuid, 'card_description', 'A rare dual court tomb — two megalithic tombs sharing a single mound, each with its own ceremonial court. Once 28 metres long, its roof stones have all collapsed.', 'In Killykeen Forest Park lies Gartnanoul, a megalithic dual tomb: two tombs in line, each with its own court, an estimated 28 metres long when built. Its roof stones are missing.', 'teaser-card-s011:fb877d92-953a-4dba-af74-64ac1330e47e:card_description', 'teaser-card-s011 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'd6a0c1c1457271d8d0707bbc2ec19e506021518e169f44ef51a53797e783f19a|042b4aeb4b19836ee4533fa0a9678e8b69f043c1ed9b53c6af1326449d84d59b|042b4aeb4b19836ee4533fa0a9678e8b69f043c1ed9b53c6af1326449d84d59b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Killykeen Forest Park lies Gartnanoul, a megalithic dual tomb: two tombs in line, each with its own court, an estimated 28 metres long when built. Its roof stones are missing."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Gartnanoul lies in Killykeen Forest Park [S1]; it is a megalithic dual tomb [S1, S2]; it has two tombs in line with each other [S2]; each tomb has its own court [S2]; it is estimated to have been 28 metres long when built [S3]; its roof stones are missing [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Gartnanoul is a megalithic court tomb [SUPPORTED: https://heritageireland.ie/unguided-sites/gartnanoul-court-cairn/]; Gartnanoul lies in Killykeen Forest Park (County Cavan, Ireland) [SUPPORTED: https://heritageireland.ie/unguided-sites/gartnanoul-court-cairn/]; Gartnanoul is a dual tomb: it has two tombs [SUPPORTED: https://heritageireland.ie/unguided-sites/gartnanoul-court-cairn/]; The two tombs of Gartnanoul are in line with each other [SUPPORTED: https://heritageireland.ie/unguided-sites/gartnanoul-court-cairn/]; Each of the two tombs of Gartnanoul has its own court [SUPPORTED: https://heritageireland.ie/unguided-sites/gartnanoul-court-cairn/]; Gartnanoul is estimated to have been 28 metres long when built [SUPPORTED: https://en.wikipedia.org/wiki/Gartnanoul]; The roof stones of Gartnanoul are missing [SUPPORTED: https://www.megalithicireland.com/Gartnanoul.html]"}]'::jsonb),
    ('fb9e7ccb-2ffd-4bb8-a78d-1e2993881090'::uuid, 'card_description', 'In 2003, a mid-4th-century inscription on one of the walls of the monument was discovered.', 'Two inscriptions discovered in 2003 at Absalom''s Tomb call the monument the tomb of Zachariah, the father of John, and the tomb of Simeon, who was a very just man.', 'teaser-card-s011:fb9e7ccb-2ffd-4bb8-a78d-1e2993881090:card_description', 'teaser-card-s011 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', '7289a6a6c36558ea9314a9c21022e047dc898321c1f42a517fff2b9085c71ae0|282fa3aa8a7dad6f5cb17c17a5072a515b67547e1e5705e8ee6ea4cfaf81ccc6|282fa3aa8a7dad6f5cb17c17a5072a515b67547e1e5705e8ee6ea4cfaf81ccc6', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Two inscriptions discovered in 2003 at Absalom''s Tomb call the monument the tomb of Zachariah, the father of John, and the tomb of Simeon, who was a very just man."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "two inscriptions were found at Absalom''s Tomb [S2, S4, S5]; the inscriptions were discovered in 2003 [S2, S4]; one inscription calls the monument the tomb of Zachariah, the father of John [S3]; the other inscription calls the monument the tomb of Simeon, who was a very just man [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Absalom''s Tomb is an ancient monumental rock-cut tomb in the Kidron Valley in Jerusalem [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Absalom]; An inscription on a wall of the monument was discovered in 2003 [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Absalom]; That inscription calls the monument the tomb of Zachariah, the father of John [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Absalom]; A second inscription was also discovered in 2003 [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Absalom]; The second inscription calls the monument the tomb of Simeon, who was a very just man [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Absalom]"}]'::jsonb),
    ('fbd17b3c-3aed-48d2-8682-df610a98a31c'::uuid, 'card_description', 'Built in 90 AD, the amphitheatre held over 20,000 spectators of chariot races and bloody hand-to-hand battles.', 'Built in 90 AD, the Arles Amphitheatre held over 20,000 spectators of chariot races and bloody hand-to-hand battles. When the Western Empire fell, it became a shelter and a fortress.', 'teaser-card-s011:fbd17b3c-3aed-48d2-8682-df610a98a31c:card_description', 'teaser-card-s011 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '6725651227ee8c751fed72ef5887f144bfd77e9144b8434d42351f45c69d4d30|c2e008f410c0388706876e527c8c97caa00daf56177c39c0a0fa143e25a5a34c|c2e008f410c0388706876e527c8c97caa00daf56177c39c0a0fa143e25a5a34c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Built in 90 AD, the Arles Amphitheatre held over 20,000 spectators of chariot races and bloody hand-to-hand battles. When the Western Empire fell, it became a shelter and a fortress."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the amphitheatre was built in 90 AD [S2]; it held over 20,000 spectators [S2]; the spectacles were chariot races and bloody hand-to-hand battles [S2]; when the Western Empire fell, it became a shelter [S5]; when the Western Empire fell, it became a fortress [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Arles Amphitheatre is a Roman amphitheatre in Arles, southern France [SUPPORTED: https://en.wikipedia.org/wiki/Arles_Amphitheatre]; It was built in 90 AD [SUPPORTED: https://en.wikipedia.org/wiki/Arles_Amphitheatre]; It held over 20,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Arles_Amphitheatre]; The spectators watched chariot races and bloody hand-to-hand battles [SUPPORTED: https://en.wikipedia.org/wiki/Arles_Amphitheatre]; With the fall of the Western Empire it became a shelter [SUPPORTED: https://en.wikipedia.org/wiki/Arles_Amphitheatre]; With the fall of the Western Empire it became a fortress [SUPPORTED: https://en.wikipedia.org/wiki/Arles_Amphitheatre]"}]'::jsonb),
    ('fead42ae-fdd5-48d1-bcc9-567c1c7873b8'::uuid, 'card_description', 'High embankments surround this Devon hillfort at 160 meters on Denbury Down. Two burial mounds occupy the center of the enclosure — the dead and the living shared the same hilltop.', 'Filling the entire hilltop of Denbury Down at 160 metres, the Iron Age hill fort of Denbury Hill has high embankments on its south and east sides and large burial mounds at its centre.', 'teaser-card-s011:fead42ae-fdd5-48d1-bcc9-567c1c7873b8:card_description', 'teaser-card-s011 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '290f5c605d7ab4628549125cfdd59536ee42b514621925315e97c9cd8220097c|7296ef253ff479b4da42a85d127f89c81d6a5d637a04283f7ee1b4cd4b976c22|7296ef253ff479b4da42a85d127f89c81d6a5d637a04283f7ee1b4cd4b976c22', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Filling the entire hilltop of Denbury Down at 160 metres, the Iron Age hill fort of Denbury Hill has high embankments on its south and east sides and large burial mounds at its centre."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the fort fills the entire hilltop of Denbury Down [S2]; the hilltop is at 160 metres [S2]; Denbury Hill is an Iron Age hill fort [S1]; it has high embankments on its south and east sides [S3]; it has large burial mounds at its centre [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Denbury Hill is an Iron Age hill fort in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Denbury_Hill]; The fort fills the entire hilltop of Denbury Down [SUPPORTED: https://en.wikipedia.org/wiki/Denbury_Hill]; The hilltop is at 160 metres [SUPPORTED: https://en.wikipedia.org/wiki/Denbury_Hill]; It has high embankments on its south and east sides [SUPPORTED: https://en.wikipedia.org/wiki/Denbury_Hill]; There are large burial mounds at its centre [SUPPORTED: https://en.wikipedia.org/wiki/Denbury_Hill]"}]'::jsonb),
    ('feeb5055-f18a-46f3-82cf-fbdfe23d72b4'::uuid, 'card_description', 'The archaeological complex, which is about 200,000 square meters, was influenced by the Wari and Chanka cultures.', 'Influenced by the Wari and Chanka cultures, Kanichi spreads over about 200,000 square meters in Ayacucho, with chullpas, ceremonial buildings and a water system of wells and springs.', 'teaser-card-s011:feeb5055-f18a-46f3-82cf-fbdfe23d72b4:card_description', 'teaser-card-s011 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'a079eb51f94c64f1d0eaa986f3ac2a0e4bc2e637f1352a8ffd72db39dcd69075|b4142f8e457c9e1694566051dcfef4883b7ca0e9a7d6cfc63aa119b7f3d0b224|b4142f8e457c9e1694566051dcfef4883b7ca0e9a7d6cfc63aa119b7f3d0b224', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Influenced by the Wari and Chanka cultures, Kanichi spreads over about 200,000 square meters in Ayacucho, with chullpas, ceremonial buildings and a water system of wells and springs."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Kanichi was influenced by the Wari and Chanka cultures [S3]; the complex covers about 200,000 square meters [S3]; it lies in Ayacucho [S2]; it includes chullpas [S4]; it includes ceremonial buildings [S4]; it has a water system of wells and springs [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Kanichi is an archaeological site in Peru, in the Ayacucho Region [SUPPORTED: https://en.wikipedia.org/wiki/Kanichi,_Peru]; Kanichi lies in Ayacucho [SUPPORTED: https://en.wikipedia.org/wiki/Kanichi,_Peru]; The complex covers about 200,000 square meters [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Kanichi,_Peru]; It was influenced by the Wari and Chanka cultures [SUPPORTED: https://en.wikipedia.org/wiki/Kanichi,_Peru]; It includes chullpas [SUPPORTED: https://en.wikipedia.org/wiki/Kanichi,_Peru]; It includes ceremonial buildings [SUPPORTED: https://en.wikipedia.org/wiki/Kanichi,_Peru]; It has a water system of wells and springs [SUPPORTED: https://en.wikipedia.org/wiki/Kanichi,_Peru]"}]'::jsonb),
    ('ff3dcd2e-6e3b-405b-a532-09b7cf71dff0'::uuid, 'card_description', NULL, 'High above a river gorge, beyond the reach of looters, stand the Sarcophagi of Carajía: figures of clay, sticks and grasses up to 2.5 meters tall, painted white, with exaggerated jawlines.', 'teaser-card-s011:ff3dcd2e-6e3b-405b-a532-09b7cf71dff0:card_description', 'teaser-card-s011 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'd47835cc43deefa2bb205929b935ccddfb27c9b0f229c920f5dd50d585a25ae5|05baad43770111b18131533a01cde32df1a01c9021aa4e7ec7e984a9e06982a2|05baad43770111b18131533a01cde32df1a01c9021aa4e7ec7e984a9e06982a2', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "High above a river gorge, beyond the reach of looters, stand the Sarcophagi of Carajía: figures of clay, sticks and grasses up to 2.5 meters tall, painted white, with exaggerated jawlines."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the sarcophagi stand high above a river gorge [S3]; their inaccessible position kept them from destruction by looters [S3]; they are made of clay, sticks and grasses [S2]; they stand up to 2.5 meters tall [S2]; they are painted white [S7]; they have exaggerated jawlines [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Sarcophagi of Carajia are Chachapoya funerary sarcophagi (figures) in the Utcubamba Valley near Chachapoyas, Peru [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]; The site is in the Utcubamba Valley, 18 km northwest of Chachapoyas, Peru [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]; The sarcophagi stand high above a river gorge [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]; Their location put them beyond the reach of looters [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]; They are made of clay, sticks and grasses [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]; They stand up to 2.5 meters tall [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]; They are painted white [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]; They have exaggerated jawlines [SUPPORTED: https://en.wikipedia.org/wiki/Sarcophagi_of_Caraj%C3%ADa]"}]'::jsonb),
    ('ff76a431-09d7-40b4-8dc5-b80211b2e246'::uuid, 'card_description', 'In about 15 BC, the Romans redrew the town as a castrum centred on the "Mons Taber", a little hill near the Generalitat and city hall buildings.', 'How the earliest settlement at Barcelona began is unclear, but in about 15 BC the Romans redrew the town as a castrum centred on the Mons Taber, a little hill near the city hall.', 'teaser-card-s011:ff76a431-09d7-40b4-8dc5-b80211b2e246:card_description', 'teaser-card-s011 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '8538f2a379574565beec739e68e2a5746c172f7797efe06d126ff8355b97778a|0859c7812ef201f56ed7bdc3a0adf7fc9cfeef82ef9bed9dc080b90a6e1a710e|0859c7812ef201f56ed7bdc3a0adf7fc9cfeef82ef9bed9dc080b90a6e1a710e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "How the earliest settlement at Barcelona began is unclear, but in about 15 BC the Romans redrew the town as a castrum centred on the Mons Taber, a little hill near the city hall."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "how the earliest settlement at Barcelona began is unclear [S1]; in about 15 BC the Romans redrew the town as a castrum [S4]; the castrum was centred on the Mons Taber [S4]; the Mons Taber is a little hill [S4]; the hill is near the city hall [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Barcelona is a city on the northeastern coast of Spain [SUPPORTED: https://en.wikipedia.org/wiki/Barcelona]; How the earliest settlement at Barcelona began is unclear [SUPPORTED: https://en.wikipedia.org/wiki/Barcelona]; The Romans redrew the town as a castrum [SUPPORTED: https://en.wikipedia.org/wiki/Barcelona]; The Romans came and founded their colony there about 15 BC [SUPPORTED: https://www.barcelona.cat/en/discoverbcn/history/roman-barcino]; The castrum was centred on the Mons Taber [SUPPORTED: https://en.wikipedia.org/wiki/Barcelona]; The Mons Taber is a little hill near the city hall [SUPPORTED: https://en.wikipedia.org/wiki/Barcelona]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 50;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s011', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s011'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s011'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 50 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s011'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s011' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
